fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // To avoid overflow in subtraction, widen to i16.
    let diff = (a as i16) - (b as i16);
    let t = tol as i16;
    // Check whether |a - b| < tol
    diff.abs() < t
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // (Optional) sanity checks; can be omitted if preconditions are guaranteed.
    debug_assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    debug_assert!(tol > 0, "Tolerance must be strictly positive");

    a.iter()
     .zip(b.iter())
     .map(|(&ai, &bi)| is_close_i8(ai, bi, tol))
     .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_close_i8() {
        assert!( is_close_i8( 10,  12,  3)); // |10 - 12| = 2 < 3
        assert!(!is_close_i8( 10,  13,  3)); // |10 - 13| = 3 == tol → false
        assert!( is_close_i8(-50, -52,  5)); // | -50 -(-52)| = 2 < 5
        assert!(!is_close_i8(127, -128, 10)); // diff = 255 → not < 10
    }

    #[test]
    fn test_np_isclose() {
        let a = vec![0,  5, -10,  50];
        let b = vec![1,  7,  -5,  45];
        let tol = 6;
        let result = np_isclose(a.clone(), b.clone(), tol);
        // |0-1|=1<6, |5-7|=2<6, |-10-(-5)|=5<6, |50-45|=5<6
        assert_eq!(result, vec![true, true, true, true]);

        // Increase tolerance to catch equality case:
        let tol = 5;
        let result = np_isclose(a, b, tol);
        // Now the third and fourth pairs have |diff|=5 == tol → false
        assert_eq!(result, vec![true, true, false, false]);
    }
}